@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/sidebar.css (Figma Sidebar 7275:14732, live 755:869; figma/06 §6.2). As wide
   as layout/sidebar (M49: 264 px from 1280 px, the 72 px rail from 640 px; Figma's frames draw 248
   and 76), 16 px padding, 4 px between items, bg/canvas with a border/subtle edge; Figma's spacer
   frames become a gap and an auto margin. Below 640 px (--nz-sm) it is not shown: the MobileTabBar
   is the navigation there. It sticks to the viewport's height and scrolls inside.

   The rail: the root is a size container named nz-sidebar, and below 10rem of content (the rail's
   40 px) NavItem folds to its icon (nav-item.css) and the header to its mark; a SidebarItem's
   Tooltip names it there. `collapsed` sets the width itself, so the same rules draw it. Public --nz-sidebar-* hooks are read once, at the
   property. */
@layer nz.components {
  .nz-sidebar {
    --_nz-sidebar-width: var(--nz-layout-sidebar);

    container: nz-sidebar / inline-size;
    position: sticky;
    inset-block-start: 0;
    z-index: var(--nz-z-chrome);
    display: none;
    flex-direction: column;
    gap: var(--nz-space-1);
    box-sizing: border-box;
    inline-size: var(--nz-sidebar-width, var(--_nz-sidebar-width));
    block-size: var(--nz-sidebar-block-size, 100dvh);
    padding: var(--nz-space-4);
    overflow-y: auto;
    border-inline-end: var(--nz-border-width-default) solid
      var(--nz-sidebar-border, var(--nz-border-subtle));
    background: var(--nz-sidebar-bg, var(--nz-bg-canvas));
    color: var(--nz-text-primary);

    /* the 72 px rail and the 264 px sidebar, the layout/sidebar token's two values */
    &[data-collapsed] {
      --_nz-sidebar-width: 4.5rem;
    }

    &[data-expanded] {
      --_nz-sidebar-width: 16.5rem;
    }

    /* shown from --nz-sm; below it the MobileTabBar is the navigation */
    @media (--nz-sm) {
      display: flex;
    }
  }

  /* Figma's Store Switcher: a 16 px-radius card, 8 px padding (Figma's 10 at the end is off the
     scale), the 32 px mark, then the name in Label/M Strong over the domain in Body/M */
  .nz-sidebar-header {
    display: flex;
    align-items: center;
    gap: var(--nz-space-2);
    box-sizing: border-box;
    min-inline-size: 0;
    margin-block-end: var(--nz-space-3);
    padding: var(--nz-space-2);
    border: var(--nz-border-width-default) solid var(--nz-border-subtle);
    border-radius: var(--nz-radius-lg);
    background: var(--nz-bg-surface);
    color: var(--nz-text-primary);
    text-decoration: none;
  }

  :where(a, button).nz-sidebar-header {
    font: inherit;
    text-align: start;
    cursor: pointer;

    @media (hover: hover) {
      &:hover {
        background: var(--nz-bg-muted);
      }
    }
  }

  /* Figma's Store mark: 32 px, an 8 px radius, bg/brand with the initial in Label/M Strong; a logo
     image fills it */
  .nz-sidebar-header-mark {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--nz-space-8);
    block-size: var(--nz-space-8);
    overflow: hidden;
    border-radius: var(--nz-radius-sm);
    background: var(--nz-sidebar-mark-bg, var(--nz-bg-brand));
    color: var(--nz-text-on-brand);
    font: var(--nz-font-label-m-strong);
    letter-spacing: var(--nz-tracking-label-m-strong);

    & > :is(img, svg) {
      inline-size: 100%;
      block-size: 100%;
      object-fit: cover;
    }
  }

  .nz-sidebar-header-text {
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
  }

  .nz-sidebar-header-title,
  .nz-sidebar-header-description {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .nz-sidebar-header-title {
    font: var(--nz-font-label-m-strong);
    letter-spacing: var(--nz-tracking-label-m-strong);
  }

  /* text/secondary: Figma's text/tertiary on bg/surface is 4.31:1 (figma/06 §6.6) */
  .nz-sidebar-header-description {
    color: var(--nz-text-secondary);
    font: var(--nz-font-body-m);
    letter-spacing: var(--nz-tracking-body-m);
  }

  .nz-sidebar-content,
  .nz-sidebar-footer {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-1);
  }

  .nz-sidebar-footer {
    margin-block-start: auto;
  }

  /* the rail: only the mark, centred on the column, as Figma's Expanded=False draws it */
  @container nz-sidebar (inline-size < 10rem) {
    .nz-sidebar-header {
      justify-content: center;
      padding: 0;
      border-color: transparent;
      background: none;
    }

    .nz-sidebar-header-text {
      position: absolute;
      inline-size: 1px;
      block-size: 1px;
      margin: -1px;
      padding: 0;
      border: 0;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }

    .nz-sidebar-content,
    .nz-sidebar-footer {
      align-items: center;
    }
  }

  @media (forced-colors: active) {
    .nz-sidebar {
      border-inline-end-color: CanvasText;
    }

    /* the mark's fill is dropped: an edge keeps its square */
    .nz-sidebar-header-mark {
      border: 1px solid CanvasText;
    }
  }
}
